GimCorpus.put(123,0,[[1,1,"אֶל יוֹאֵל בֶּן פְּתוּאֵל. בֶּן שְׁמוּאֵל הַנָּבִיא, שֶׁפִּתָּה לָאֵל בִּתְפִלָּתוֹ, יֵשׁ אוֹמְרִים שֶׁנְּבוּאָה זוֹ נֶאֶמְרָה בְּאוֹתָן שֶׁבַע שָׁנִים שֶׁאָמַר אֱלִישָׁע (מלכים ב ח:א) ״כִּי קָרָא ה׳ לָרָעָב וְגוֹ׳״ וּבִימֵי יְהוֹרָם בֶּן אַחְאָב הָיוּ. וּבַהֲלָכוֹת גְּדוֹלוֹת נִמְצָא יוֹאֵל וְנָחוּם וַחֲבַקּוּק הָיוּ בִּימֵי מְנַשֶּׁה:",1,0],[1,2,"הֲהָיְתָה זֹּאת. הָאֲמוּרָה לְמַטָּה:",1,0],[1,4,"יֶתֶר הַגָּזָם וְגוֹ׳. גָּזָם אַרְבֶּה יֶלֶק חָסִיל מִינֵי גּוֹבַאי הֵם וְנִתְנַבֵּא עֲלֵיהֶם שֶׁיָּבֹאוּ וּבָאוּ בְּאוֹתָן הַיָּמִים וְכִלּוּ כָּל פְּרִי הָעֵץ וִירַק הַשָּׂדֶה:",1,0],[1,5,"עָסִיס. יַיִן הַטּוֹב:",1,0],[1,6,"גּוֹי עָלָה עַל אַרְצִי. הַגּוֹבַאי הַזֶּה כִּנָּהוּ כְּצָבָא גּוֹי:",1,0],[1,6,"וּמְתַלְּעוֹת. הֵן הַשִּׁנַּיִם הַגַּסִּין שֶׁלּוֹעֵס בָּהֶן:",2,0],[1,7,"לִקְצָפָה. לְמַפַּח נֶפֶשׁ:",1,0],[1,7,"חָשֹׂף חֲשָׂפָהּ וְהִשְׁלִיךְ. קִלּוּף קְלִפּוֹת הָעֵץ וְהִשְׁלִיכוֹ עַד הִלְבִּינוּ זְמוֹרוֹת הַגֶּפֶן:",2,0],[1,8,"אֱלִי. ׳קִינָה׳ מְתַרְגְּמִינָן ׳אִילְיָא׳:",1,0],[1,9,"הָכְרַת. כְּמוֹ ׳נִכְרַת׳, הֵ״א הַנְּקוּדָה בְּחָטַף קָמַץ עוֹמֶדֶת בִּמְקוֹם נוּ״ן כְּמוֹ ״וְחַיַּת הַשָּׂדֶה הָשְׁלְמָה לָךְ״ (איוב ה:כג):",1,0],[1,11,"הוֹבִישׁוּ. הִכָּלְמוּ:",1,0],[1,11,"אִכָּרִים. מַנְהִיגֵי הַמַּחֲרֵשָׁה:",2,0],[1,11,"עַל חִטָּה וְעַל שְׂעוֹרָה. מוּסָב עַל אִכָּרִים, וְעַל הַכּוֹרְמִים אָמַר:",3,0],[1,12,"הַגֶּפֶן הוֹבִישָׁה וְהַתְּאֵנָה אֻמְלָלָה. נִכְרְתָה פָּסַק פִּרְיָהּ:",1,0],[1,12,"הוֹבִישׁ. כְּמוֹ ׳יָבֵשׁ׳:",2,0],[1,14,"קַדְּשׁוּ צוֹם. הַזְמִינוּ צוֹם:",1,0],[1,14,"עֲצָרָה. אֲסִיפָה:",2,0],[1,15,"אֲהָהּ. לְשׁוֹן גְּנִיחַת יְלָלָה:",1,0],[1,15,"וּכְשׁוֹד. וּכְבִזַּת שׁוֹדְדִים:",2,0],[1,15,"יָבוֹא. מֵאֵת הַמָּקוֹם:",3,0],[1,16,"נֶגֶד עֵינֵינוּ. אָנוּ רוֹאִים:",1,0],[1,17,"עָבְשׁוּ. הֶעֱלוּ חֲלוּדָה וְעִפּוּשׁ בְּלַעַ״ז מוי״ישיר:",1,0],[1,17,"פְּרֻדּוֹת. תִּרְגֵּם יוֹנָתָן ״גַּרְבֵּי חַמְרָא״:",2,0],[1,17,"מֶגְרְפֹתֵיהֶם. תַּרְגּוּם יוֹנָתָן ״מְגוּפָתְהוֹן״ מְגוּפַת כִּסּוּי הֶחָבִיּוֹת:",3,0],[1,17,"נָשַׁמּוּ אוֹצָרוֹת. שֶׁל יַיִן וְשֶׁל שֶׁמֶן:",4,0],[1,17,"מַמְּגֻרוֹת. מְגוּרוֹת שֶׁל חִטִּין:",5,0],[1,18,"נָבֹכוּ. נִתְעַרְבְּלוּ וְנִסְגְּרוּ וְתָעוּ בַּיְּעָרִים וּבַמִּדְבָּרוֹת:",1,0],[1,18,"נֶאְשָׁמוּ. נִתְקַלְקְלוּ בְּאַשְׁמָתָן:",2,0],[1,19,"נְאוֹת מִדְבָּר. לְשׁוֹן ׳נָוֶה׳:",1,0],[1,20,"תַּעֲרוֹג. תִּצְעַק כַּאֲשֶׁר פָּתַר דּוּנַשׁ עָרַג לְאַיָּלִים נָהַם לִשְׁחָלִים וְגָעָה לַעֲגָלִים וְצָהַל לְסוּסִים צִפְצוּף לְעוֹפוֹת וְנָבַח לִכְלָבִים:",1,0],[2,1,"תִּקְעוּ שׁוֹפָר. לְהַשְׁמִיעָם שֶׁיָּשׁוּבוּ בִּתְשׁוּבָה בְּטֶרֶם תְּבוֹאתָם הָרָעָה הַזֹּאת:",1,0],[2,1,"יוֹם ה׳. מַה שֶׁאָמַרְנוּ לְמַעְלָה:",2,0],[2,2,"כְּשַׁחַר פָּרֻשׂ עַל הֶהָרִים. הָאַרְבֶּה וְהַגָּזָם נִפְרָשִׂים עַל הֶהָרִים כְּשַׁחַר הַנִּפְרָשׂ בְּכָל הָעוֹלָם:",1,0],[2,2,"כָּמֹהוּ לֹא נִהְיָה מִן הָעוֹלָם. לָבוֹא כָּל הַמִּינִים הַלָּלוּ זֶה אַחַר זֶה, אֲבָל מִין אַרְבֶּה לְבַדּוֹ לֹא הָיָה כְּמוֹ אוֹתוֹ שֶׁל מִצְרַיִם שֶׁנֶּאֱמַר ״וְאַחֲרָיו לֹא יִהְיֶה כֵּן״ (שמות י:יד):",2,0],[2,3,"לְפָנָיו אָכְלָה אֵשׁ. מַשְׁחִיתִים אֶת הַכֹּל כְּאִלּוּ אֵשׁ אוֹכֶלֶת לִפְנֵיהֶם וְלֶהָבָה מְלַהֶטֶת אַחֲרֵיהֶם:",1,0],[2,3,"כְּגַן עֵדֶן. הָיְתָה הָאָרֶץ לִפְנֵי בּוֹאוֹ וְאַחַר שֶׁיֵּלֵךְ הִנִּיחַ אֶת הָאָרֶץ כְּמִדְבַּר שְׁמָמָה:",2,0],[2,4,"כְּמַרְאֵה סוּסִים מַרְאֵהוּ. בִּמְרוּצָתוֹ:",1,0],[2,5,"כְּקוֹל לַהַב. הָאוֹכֶלֶת קַשׁ מַשְׁמַעַת קוֹל:",1,0],[2,5,"עֱרוּךְ מִלְחָמָה. לְפִי שֶׁהוּא דָבוּק נָקוּד חֲטַף סְגוֹל:",2,0],[2,6,"קִבְּצוּ פָּארוּר. שַׁחֲרוּת כַּקְּדֵרָה כְּמָה דְאַתְּ אָמַר ״וּבִשְּׁלוּ בַפָּרוּר״ (במדבר יא:ח). וְאָלֶף הַכְּתוּבָה יְתֵרָה הִיא וְאֵינָהּ נִקְרֵאת:",1,0],[2,7,"וְלֹא יְעַבְּטוּן. אֵין לוֹ דִמְיוֹן וּפִתְרוֹנוֹ לְפִי עִנְיָנוֹ לֹא יְעַקְּלוּן:",1,0],[2,8,"וּבְעַד הַשֶּׁלַח. כְּמוֹ בְּעַד הַחַלּוֹנִים עַל פְּנֵי כְּלֵי זַיִן יִפְּלוּ וְיַחֲנוּ:",1,0],[2,8,"וְלֹא יִבְצָעוּ. וְלֹא יְקַבְּלוּן מָמוֹן. וְיוֹנָתָן פָּתַר בּוֹ לְשׁוֹן ׳שְׁלִיחוּת׳ בִּשְׁבִיל שְׁלִיחוּת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַפִּילִין עַצְמָן וּבֶצַע כֶּסֶף לֹא לָקָחוּ:",2,0],[2,9,"בָּעִיר יָשֹׁקּוּ. לְשׁוֹן הַשְׁמָעַת קוֹל כְּמוֹ ״כְּמַשַּׁק גֵּבִים״ (ישעיהו לג:ד) ״דֹּב שׁוֹקֵק״ (משלי כח) ״מִמְשַׁק חָרוּל״ (צפניה ב:ט). וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן ׳נֶשֶׁק׳ ״מִזְדַּיְּנִין״:",1,0],[2,10,"רָעֲשׁוּ שָׁמָיִם. בִּשְׁבִיל פֻּרְעָנוּת הַבָּאָה עַל יִשְׂרָאֵל רוֹגְזִים וְרוֹעֲשִׁים:",1,0],[2,10,"אָסְפוּ נָגְהָם. הִכְנִיסוּ אוֹרָן:",2,0],[2,11,"וַה׳ נָתַן. עֲלֵיהֶם קוֹלוֹ בְּמַאֲמַר נְבִיאָיו לִפְנֵי שָׁלְחוֹ בָּהֶם אֶת חֵילוֹ זֶה:",1,0],[2,11,"כִּי רַב מְאֹד מַחֲנֵהוּ. אֲשֶׁר יִשְׁלַח בָּכֶם אִם לֹא תֵּטִיבוּן:",2,0],[2,13,"וְאַל בִּגְדֵיכֶם. כִּי אֵינִי חָשׁ לִקְרִיעַת בִּגְדֵיכֶם. דָּבָר אַחֵר קִרְעוּ לְבַבְכֶם וְאַל תִּצְטָרְכוּ לִקְרֹעַ בִּגְדֵיכֶם מֵחֲמַת אֵבֶל:",1,0],[2,13,"וְנִחָם עַל הָרָעָה. נֶהְפַּךְ לְמַחֲשָׁבָה אַחֶרֶת:",2,0],[2,14,"מִי יוֹדֵעַ. שֶׁיֵּשׁ בּוֹ עָוֹן יָשׁוּב וְנִחָם:",1,0],[2,14,"וְהִשְׁאִיר. הֶחָסִיל וְהַגָּזָם אַחֲרָיו בְּרָכָה עַל יְדֵי הַתְּשׁוּבָה תָּבֹא בְּרָכָה בַּפֵּרוֹת:",2,0],[2,16,"קִבְצוּ זְקֵנִים. מִמִּשְׁקְלוֹת ״שְׁלַח קְבֹץ אֵלַי״ (מלכים א יח:יט) לְשׁוֹן רָפֵי וְקַל:",1,0],[2,17,"לְחֶרְפָּה. לְגִדּוּפִין:",1,0],[2,17,"לִמְשָׁל בָּם גּוֹיִם. לְשׁוֹן מָשָׁל וּשְׁנִינָה:",2,0],[2,18,"וַיְקַנֵּא ה׳ לְאַרְצוֹ. לְשׁוֹן ״הַמְקַנֵּא אַתָּה לִי״ (במדבר יא:כט) נִכְנְסָה בְּלִבּוֹ צָרָתָהּ וְנִלְחַם בְּמִלְחַמְתָּהּ וְנִתְעַסֵּק בְּצָרְכֶיהָ. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לְשׁוֹן ׳הַתְרָאָה׳, הִתְרָה בַּגּוֹבַאי עַל עִסְקֵי אַרְצוֹ:",1,0],[2,19,"חֶרְפָּה. גִּדּוּף שֶׁיִּקְרְאוּ אֶתְכֶם חַסְרֵי לֶחֶם:",1,0],[2,20,"וְאֶת הַצְּפוֹנִי. יֵשׁ לְפוֹתְרוֹ עַל חֵיל הָאַרְבֶּה וְעָלָיו נוֹפֵל לְשׁוֹן הִדַּחְתִּיו אֶל אֶרֶץ צִיָּה וּשְׁמָמָה. דָּבָר אַחֵר הָעָם הַבָּא מִצָּפוֹן מַלְכֵי אַשּׁוּר וְרַבּוֹתֵינוּ אוֹמְרִים זֶה יֵצֶר הָרָע שֶׁצָּפוּן בִּלְבָבוֹ שֶׁל אָדָם:",1,0],[2,20,"הַקַּדְמוֹנִי. הַמִּזְרָחִי. וְרַבּוֹתֵינוּ שֶׁפֵּרְשׁוּ בְּיֵצֶר הָרָע דָּרְשׁוּ שְׁנֵי הַיָּמִים הַלָּלוּ בְּמִקְדָּשׁ רִאשׁוֹן וּבְמִקְדָּשׁ שֵׁנִי וְכֵן פֵּרְשׁוּהוּ עַל אֲשֶׁר שָׂם פָּנָיו בְּמִקְדָּשׁ רִאשׁוֹן וְשֵׁנִי וְהֶחֱרִיבָם. וּלְפִי הַתַּרְגּוּם שֶׁפֵּרְשׁוּ עַל חֵיל מֶלֶךְ אַשּׁוּר צָרִיךְ לוֹמַר פָּנָיו (אֶל) הַיָּם הַקַּדְמוֹנִי מִקְצָת חֵילוֹ אֶשְׁלַח לְמִזְרָח וּמִקְצָתוֹ לְמַעֲרָב:",2,0],[2,20,"צַחֲנָתוֹ. בָּאְשׁוֹ יוֹרֶה עָלָיו שֶׁהוּא לְשׁוֹן זֹהַם וְטִנּוּף:",3,0],[2,20,"כִּי הִגְדִּיל לַעֲשׂוֹת. רָאָה שֶׁפָּשַׁט יָדוֹ בַּגְּדוֹלִים:",4,0],[2,21,"אַל תִּירְאִי אֲדָמָה. אֶרֶץ יִשְׂרָאֵל אִם תָּשׁוּבִי בִּתְשׁוּבָה:",1,0],[2,23,"אֶת הַמּוֹרֶה. אֶת נְבִיאֵיכֶם הַמּוֹרִים אֶתְכֶם לָשׁוּב אֵלַי כְּדֵי לְצַדֵּק אֶתְכֶם:",1,0],[2,23,"מוֹרֶה וּמַלְקוֹשׁ. כְּמוֹ ״יוֹרֶה וּמַלְקוֹשׁ״ (דברים יא:יד):",2,0],[2,23,"בָּרִאשׁוֹן. בְּנִיסָן וְאַף עַל פִּי שֶׁהַיּוֹרֶה הִיא רְבִיעָה רִאשׁוֹנָה הַיּוֹרֶדֶת עַל הַזֶּרַע וְהוּא בְּמַרְחֶשְׁוָן, אוֹתָהּ שָׁנָה בְּנִיסָן זָרְעוּ כְּמוֹ שֶׁמְּפֹרָשׁ בְּמַסֶּכֶת תַּעֲנִית שֶׁגָּדְלָה הַתְּבוּאָה בְּאַחַד עָשָׂר יוֹם:",3,0],[2,24,"וְהֵשִׁיקוּ. לְשׁוֹן הַשְׁמָעַת קוֹל כְּשֶׁהַקִּלּוּחַ יוֹרֵד מִן הַגַּת אֶל תּוֹךְ הַיֶּקֶב וְהוּא הַבּוֹר שֶׁלִּפְנֵי הַגַּת:",1,0],[3,1,"וְהָיָה אַחֲרֵי כֵן. לֶעָתִיד לָבֹא:",1,0],[3,1,"עַל כָּל בָּשָׂר. עַל מִי שֶׁנַּעֲשָׂה לִבּוֹ רַךְ כַּבָּשָׂר דֻּגְמַת ״וְנָתַתִּי לָכֶם לֵב בָּשָׂר״ (יחזקאל לו:כו):",2,0],[3,3,"וְתִמְרוֹת עָשָׁן. זְקִיפוּת מַעֲלֵה עָשָׁן בְּגֹבַהּ:",1,0],[3,4,"יֵהָפֵךְ לְחֹשֶׁךְ. לְבַיֵּשׁ אֶת הַמִּשְׁתַּחֲוִים לַחַמָּה:",1,0],[3,5,"וְהָיָה כָּל אֲשֶׁר יִקְרָא וְגוֹ׳ כַּאֲשֶׁר אָמַר. וְהֵיכָן אָמַר ״וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם ה׳ נִקְרָא עָלֶיךָ״ (דברים כח:י):",1,0],[3,5,"וּבַשְּׂרִידִים. בַּשְּׁאֵרִית אֲשֶׁר יוֹתִיר:",2,0],[3,5,"אֲשֶׁר ה׳ קוֹרֵא. לְשׁוֹן קְרוּאִים לִסְעוּדָה אוֹ לַעֲבוֹדַת הַמֶּלֶךְ לְשׁוֹן ׳הַזְמָנָה׳:",3,0],[4,2,"אֶל עֵמֶק יְהוֹשָׁפָט. אֵרֵד עִמָּם בְּעֹמֶק הַדִּין, יְהוֹשָׁפָט מִשְׁפָּטִי יָהּ:",1,0],[4,3,"יַדּוּ גוֹרָל. כְּמוֹ ״וַיַּדּוּ אֶבֶן בִּי״ (איכה ג:נג):",1,0],[4,4,"הַגְּמוּל אַתֶּם מְשַׁלְּמִים. זֶהוּ הַגְּמוּל שֶׁנָּתַן שְׁלֹמֹה לְחִירָם מֶלֶךְ צוֹר עֶשְׂרִים עִיר (מלכים א ט):",1,0],[4,4,"קַל מְהֵרָה. לְשׁוֹן ׳זְרִיזוּת׳:",2,0],[4,8,"לִשְׁבָאיִם וְגוֹ׳. לִבְנֵי שְׁבָא:",1,0],[4,8,"כִּי ה׳ דִּבֵּר. וְהֵיכָן דִּבֵּר ״עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו״ (בראשית ט:כה) כֵּן מְפֹרָשׁ בִּמְכִילְתִּין:",2,0],[4,9,"קַדְּשׁוּ מִלְחָמָה. אִם תּוּכְלוּן אַתֶּם לְהִלָּחֵם כְּנֶגְדִּי:",1,0],[4,10,"אִתֵּיכֶם. קלטר״ש בְּלַעַ״ז:",1,0],[4,10,"וּמַזְמְרוֹתֵיכֶם. שרפש״א בְּלַעַ״ז:",2,0],[4,11,"עוּשׁוּ. כְּמוֹ ׳חוּשׁוּ׳ כָּךְ חִבְּרוֹ מְנַחֵם. וְיוֹנָתָן תִּרְגֵּם ״יִתְכַּנְּשׁוּן״, וְאוֹמֵר אֲנִי שֶׁהוּא לְשׁוֹן ׳עֶשֶׁת בַּרְזֶל׳ הַמְכֻנָּס יַחַד מש״א בְּלַעַ״ז וְאֵין תָּי״ו בּוֹ יְסוֹד:",1,0],[4,11,"שָׁמָּה הִנְחַת ה׳ גִּבּוֹרֶיךָ. שָׁם בִּקְבוּצַת עֵמֶק יְהוֹשָׁפָט יִשְׁבּוֹר גְּבוּרַתְכֶם כֵּן תִּרְגֵּם יוֹנָתָן. וְאֵינִי יוֹדֵעַ אִם לְשׁוֹן אֲרָמִי הוֹרָדָה אוֹ לְשׁוֹן חֲתַת וְהַנּוּ״ן בּוֹ נוֹפֵל כְּמוֹ (דניאל ב:כה) ״הַנְעֵל לְדָנִיֵּאל קֳדָם מַלְכָּא״, שֶׁאֵין בּוֹ אוֹת שֹׁרֶשׁ אֶלָּא עַל:",2,0],[4,13,"שִׁלְחוּ מַגָּל וְגוֹ׳. שִׁלְחוּ חֲרָבוֹת אוֹתָם הַהוֹלְכִים בִּשְׁלִיחוּתִי לְחַבֵּל אֶת אוֹיְבֵי ה׳:",1,0],[4,13,"כִּי בָשַׁל קָצִיר. כְּלוֹמַר כִּי הִגִּיעַ עִתָּם וְדִמָּה הַדָּבָר לְקָצִיר שֶׁקּוֹצְרִים אוֹתוֹ בְּמַגָּלוֹת כְּשֶׁגָּמַר בִּשּׁוּלוֹ:",2,0],[4,13,"בֹּאוּ רְדוּ כִּי מָלְאָה גַת. מִן הָעֲנָבִים בֹּאוּ וְדִרְכוּ אוֹתָם כְּלוֹמַר נִתְמַלָּא סְאַת עֲוֹנָם. רְדוּ לְשׁוֹן כְּבִישָׁה וְרִדּוּי כְּמוֹ ״וּרְדוּ בִדְגַת הַיָּם״ (בראשית א:כח):",3,0],[4,13,"הֵשִׁיקוּ הַיְקָבִים. קוֹל קִלּוּחַ הַיְקָבִים הַיּוֹרֵד תּוֹךְ הַבּוֹר שֶׁלִּפְנֵי הַגִּתּוֹת נִשְׁמָע:",4,0],[4,14,"בְּעֵמֶק הֶחָרוּץ. שֶׁשָּׁם חָרוּץ שֶׁהַמִּשְׁפָּט אֱמֶת וְכֵן תִּרְגֵּם יוֹנָתָן ״מֵישַׁר פִּלּוּג דִּינָא״:",1,0],[4,15,"אָסְפוּ נָגְהָם. הִכְנִיסוּ אוֹרָם:",1,0],[4,16,"מִצִּיּוֹן יִשְׁאָג. מִמַּה שֶּׁעָשׂוּ לְצִיּוֹן:",1,0],[4,16,"וְרָעֲשׁוּ שָׁמַיִם וָאָרֶץ. יִפָּרַע מִשָּׂרִים שֶׁל מַעְלָה (שָׂרֵי הַכַּשְׂדִּים) וְאַחַר כָּךְ מִן (הַכַּשְׂדִּים):",2,0],[4,16,"מַחֲסֶה. לְשׁוֹן ׳כִּסּוּי׳, וּבְלַעַ״ז אבריאיי״ל:",3,0],[4,18,"אֲפִיקֵי. מְקוֹם מוֹצָא מַיִם:",1,0],[4,18,"וְהִשְׁקָה אֶת נַחַל הַשִּׁטִּים. כְּמַשְׁמָעוֹ ״וּמַשְׁקֵי יָת מֵישַׁר שִׁטִּים״. וּמִדְרָשׁוֹ יְכַפֵּר עַל עֲוֹן פְּעוֹר (עיין זכריה יד):",2,0],[4,19,"מִצְרַיִם וְגוֹ׳. סְמָכָן זֶה לָזֶה לְפֻרְעָנִיּוֹת אַתָּה מוֹצֵא שֶׁאִלּוּלֵי מִצְרַיִם לֹא הָיְתָה אֱדוֹם שֶׁנֶּאֱמַר (מלכים א יא:טז) ״כִּי שֵׁשֶׁת חֳדָשִׁים יָשַׁב יוֹאָב עַד הַכְרִית כָּל זָכָר בֶּאֱדוֹם״ וּכְתִיב (שם יז-כא) ״וַיִּבְרַח אֲדַד הוּא וַאֲנָשִׁים אֲדוֹמִיִּים וַיִּמְצָא הֲדַד חֵן בְּעֵינֵי פַרְעֹה וְגוֹמֵר וַהֲדַד שָׁמַע כִּי שָׁכַב דָּוִד עִם אֲבוֹתָיו וְגוֹמֵר״ וּבָאַחֲרוֹנָה ״וַיְהִי לְשָׂטָן לִשְׁלֹמֹה״ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֲנִי אֲכַלֶּה זוֹ וָזוֹ:",1,0],[4,19,"מֵחֲמַס בְּנֵי יְהוּדָה. בִּשְׁבִיל חָמָס שֶׁעָשׂוּ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִבְנֵי יְהוּדָה אֲשֶׁר שָׁפְכוּ אֶת דָּמָם:",2,0],[4,21,"וְנִקֵּיתִי דָּמָם לֹא נִקֵּיתִי. וְאַף אִם אֲנַקֶּה אוֹתָם מִשְּׁאָר עֲבֵירוֹת שֶׁבְּיָדָם וּמֵרָעוֹת שֶׁעָשׂוּ לִי, דָּמָם שֶׁל בְּנֵי יְהוּדָה לֹא אֲנַקֶּה מֵהֶם. אֵימָתַי תִּהְיֶה זֹאת, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹכֵן בְּצִיּוֹן:",1,0]]);
